import logging
import openstack.compute.v2.server as openstack_server
from .exceptions import AmbiguousInstanceName
from .exceptions import OpenstackException
from .connection import verify_connection


class Server(object):
    SERVER_NOT_FOUND = "NOT_FOUND"
    SERVER_STATUS_ACTIVE = 'ACTIVE'
    SERVER_STATUS_SHUTOFF = 'SHUTOFF'
    REBOOT_TYPE_SOFT = 'SOFT'
    REBOOT_TYPE_HARD = 'HARD'

    def __init__(self, connection):
        verify_connection(connection)
        self.connection = connection

    def get_status(self, instance_name):
        instance = self.connection.list_servers(
            filters={"name": instance_name})
        if len(instance) > 1:
            raise AmbiguousInstanceName
        elif len(instance) == 1:
            status = instance[0]["vm_state"].upper()
        else:
            status = self.SERVER_NOT_FOUND
        return status

    def start(self, name_or_id):
        server_instance = self._find_server(name_or_id)
        self._verify_server_status_shutoff(server_instance)
        logging.info('Starting server: {}'.format(server_instance.name))
        self.connection.compute.start_server(server_instance)

    def stop(self, name_or_id):
        server_instance = self._find_server(name_or_id)
        self._verify_server_status_active(server_instance)
        logging.info('Stopping server: {}'.format(server_instance.name))
        self.connection.compute.stop_server(server_instance)

    def reboot_soft(self, name_or_id):
        return self._reboot_server(name_or_id,
                                   reboot_type=self.REBOOT_TYPE_SOFT)

    def reboot_hard(self, name_or_id):
        return self._reboot_server(name_or_id,
                                   reboot_type=self.REBOOT_TYPE_HARD)

    def _reboot_server(self, name_or_id, reboot_type):
        server_instance = self._find_server(name_or_id)
        self._verify_server_status_active(server_instance)
        self._reboot_server_instance(server_instance=server_instance,
                                     reboot_type=reboot_type)
        return self._find_server(server_instance.id).status

    def _reboot_server_instance(self, server_instance, reboot_type):
        logging.info('Rebooting server: {}\nReboot type: {}'.format(
            server_instance.name, reboot_type))
        self.connection.compute.reboot_server(server=server_instance,
                                              reboot_type=reboot_type)

    def _find_server(self, name_or_id):
        server_instance = openstack_server.Server.find(
            session=self.connection.session,
            name_or_id=name_or_id,
            ignore_missing=False)
        # Returned server_instance does not have status
        # if it has been found by name
        if server_instance.id != name_or_id:
            server_instance = openstack_server.Server.find(
                session=self.connection.session,
                name_or_id=server_instance.id,
                ignore_missing=False)
        return server_instance

    def _verify_server_status_active(self, server_instance):
        if server_instance.status != self.SERVER_STATUS_ACTIVE:
            exc_msg = "Cannot reboot a server instance with status: {}"
            exc_msg += "\nServer name: {}"
            exc_msg = exc_msg.format(server_instance.status,
                                     server_instance.name)
            raise OpenstackException(exc_msg)

    def _verify_server_status_shutoff(self, server_instance):
        if server_instance.status != self.SERVER_STATUS_SHUTOFF:
            exc_msg = "Cannot start a server instance with status: {}"
            exc_msg += "\nServer name: {}"
            exc_msg = exc_msg.format(server_instance.status,
                                     server_instance.name)
            raise OpenstackException(exc_msg)
